INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Programmierung > Skripte
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Skripte in einer IT-Umgebung ohne vorherige Tests produktiv eingesetzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber riskant und unsicher"}, {"text": "Nein", "correct": false, "because": "Tests sind Best Practice, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Skripte für die Automatisierung von IT-Systemen immer in einer höheren Programmiersprache wie Python geschrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Shell-Skripte oder Batch-Dateien sind ebenfalls effektiv"}, {"text": "Ja", "correct": false, "because": "Einfachere Skriptsprachen sind oft ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, mit Skripten Hardwarekomponenten direkt anzusteuern, ohne Treiber oder Schnittstellen?', 2, '[{"text": "Nein", "correct": true, "because": "Skripte benötigen Abstraktionsebenen wie APIs oder Treiber"}, {"text": "Ja", "correct": false, "because": "Direkter Hardwarezugriff ist nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Skripte allein ein komplettes IT-System ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Skripte automatisieren Teilaufgaben, nicht ganze Systeme"}, {"text": "Ja", "correct": false, "because": "Skripte sind nur Werkzeuge, keine Systeme"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Skripte in der Programmierung immer schneller als kompilierte Programme?', 2, '[{"text": "Nein", "correct": true, "because": "Interpretierte Skripte sind oft langsamer als kompilierter Code"}, {"text": "Ja", "correct": false, "because": "Ausführungsgeschwindigkeit hängt von der Sprache ab"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Skriptsprache wird häufig für die Automatisierung unter Linux verwendet?', 3, '[{"text": "Bash", "correct": true, "because": "Standard in Unix-ähnlichen Systemen"}, {"text": "PowerShell", "correct": false, "because": "Primär für Windows"}, {"text": "JavaScript", "correct": false, "because": "Meist für Webentwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion erfüllt ein Skript typischerweise in der IT?', 2, '[{"text": "Automatisierung wiederkehrender Aufgaben", "correct": true, "because": "Hauptzweck von Skripten"}, {"text": "Entwicklung komplexer Benutzeroberflächen", "correct": false, "because": "Nicht typisch für Skripte"}, {"text": "Hardware-Diagnose", "correct": false, "because": "Nur indirekt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Erstellung eines Skripts besonders kritisch?', 2, '[{"text": "Fehlerbehandlung", "correct": true, "because": "Verhindert Abstürze bei unerwarteten Eingaben"}, {"text": "Farbliche Syntaxhervorhebung", "correct": false, "because": "Nur für Lesbarkeit"}, {"text": "Maximale Zeilenlänge", "correct": false, "because": "Stilistisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein häufiger Einsatzzweck von Skripten in der Systemadministration?', 2, '[{"text": "Benutzerkontenverwaltung", "correct": true, "because": "Effiziente Massenbearbeitung"}, {"text": "Datenbankdesign", "correct": false, "because": "Eher Aufgabe von Programmen"}, {"text": "Netzwerkhardware-Konfiguration", "correct": false, "because": "Eher manuell oder via Firmware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft macht ein Skript wartungsfreundlich?', 3, '[{"text": "Kommentierte Codezeilen", "correct": true, "because": "Erleichtert Verständnis und Anpassung"}, {"text": "Minimale Zeilenanzahl", "correct": false, "because": "Kürze kann Lesbarkeit mindern"}, {"text": "Hohe Ausführungsgeschwindigkeit", "correct": false, "because": "Unabhängig von Wartung"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben können mit Skripten in der Programmierung automatisiert werden?', 4, '[{"text": "Dateibereinigung", "correct": true, "because": "Löschen alter Dateien"}, {"text": "Benutzeranlage", "correct": true, "because": "Massenverwaltung"}, {"text": "Systemüberwachung", "correct": true, "because": "Statusprüfungen"}, {"text": "Grafikdesign", "correct": false, "because": "Nicht typisch für Skripte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprachen eignen sich für Skripte in der IT?', 3, '[{"text": "Python", "correct": true, "because": "Flexibel und weit verbreitet"}, {"text": "Bash", "correct": true, "because": "Unix-Standard"}, {"text": "PowerShell", "correct": true, "because": "Windows-Automatisierung"}, {"text": "C++", "correct": false, "because": "Kompilierte Sprache"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Skripte gegenüber manuellen Prozessen?', 4, '[{"text": "Zeitersparnis", "correct": true, "because": "Wiederholungen werden automatisiert"}, {"text": "Fehlerreduktion", "correct": true, "because": "Konsistente Ausführung"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Einmal geschrieben, mehrfach nutzbar"}, {"text": "Höhere Hardwarekosten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei der Skripterstellung auftreten?', 3, '[{"text": "Fehlende Berechtigungen", "correct": true, "because": "Skripte scheitern ohne Zugriff"}, {"text": "Unbekannte Variablen", "correct": true, "because": "Unerwartete Eingaben"}, {"text": "Plattformabhängigkeit", "correct": true, "because": "Nicht überall lauffähig"}, {"text": "Zu schnelle Ausführung", "correct": false, "because": "Kein echtes Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sollte ein robustes Skript enthalten?', 3, '[{"text": "Fehlerprüfung", "correct": true, "because": "Fängt Probleme ab"}, {"text": "Logging", "correct": true, "because": "Nachverfolgbarkeit"}, {"text": "Konfigurationsvariablen", "correct": true, "because": "Flexibilität"}, {"text": "3D-Animationen", "correct": false, "because": "Irrelevant für Skripte"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Skripte können mehrere Aufgaben gleichzeitig ausführen. b) Skripte sind immer plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Multitasking ja, Plattformabhängigkeit möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Skript kann durch Parameter flexibel gestaltet werden. b) Skripte benötigen immer eine grafische Oberfläche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Parameter ja, GUI nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bash-Skripte sind nur auf Linux-Systemen lauffähig. b) Skripte können mit Datenbanken interagieren.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Bash auch auf Unix, Datenbanken ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Fehlerbehandlung in Skripten ist optional. b) Skripte können andere Skripte aufrufen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Fehlerbehandlung wichtig, Aufruf möglich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Skripte sind für einmalige Aufgaben ungeeignet. b) Kommentare in Skripten verbessern die Wartbarkeit.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Einmalig möglich, Kommentare hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

